WITH base AS (SELECT id, full_name, email, dept_id, manager_id, job_title, salary, hire_date, is_remote, level, SUBSTRING(full_name, 1, 3) AS full_name_prefix, SUBSTRING(level, 1, 3) AS level_prefix FROM employees WHERE job_title IS NOT NULL AND hire_date > DATE '2023-05-13') SELECT *, RANK() OVER (PARTITION BY job_title, level ORDER BY salary) AS latest_rank FROM base QUALIFY latest_rank = 1
